<template><section class="native-page" aria-labelledby="native-title"><p class="native-page__eyebrow">ASII-29 · Extensión móvil/escritorio</p><h1 id="native-title">Acciones offline y sincronización</h1><p class="native-page__hint">Prototipo acotado: prepara una acción local. La sincronización de esta entrega es simulada: no envía datos a un servicio remoto.</p><p v-if="message" class="native-page__message" role="status">{{ message }}</p><p v-if="error" class="native-page__error" role="alert">{{ error }}</p><div class="native-page__grid"><form class="native-page__card" @submit.prevent="prepare"><h2>Preparar acción</h2><label>Tipo<input v-model="form.kind" required /></label><label>Payload JSON<textarea v-model="form.payload" rows="5" required /></label><button :disabled="busy">Guardar localmente</button></form><section class="native-page__card"><h2>Cola local</h2><p v-if="!actions.length">No hay acciones pendientes.</p><ul v-else><li v-for="item in actions" :key="item.id"><strong>{{ item.kind }}</strong><span>{{ item.status }}</span><small>{{ item.id }}</small></li></ul><button :disabled="busy || !pending" @click="sync">Sincronizar en línea</button></section></div></section></template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'; import api from '@/plugins/axios';
const actions=ref([]); const error=ref(''); const message=ref(''); const busy=ref(false); const form=reactive({kind:'lab_result_preview',payload:'{"result_id":"res-001"}'}); const pending=computed(()=>actions.value.some(item=>item.status==='pendiente_sincronizar'));
async function load(){try{const {data}=await api.get('/nativephp/actions');actions.value=data.data??[]}catch(e){error.value=e.response?.data?.error??'No fue posible cargar la cola local.'}}
async function prepare(){busy.value=true;error.value='';try{const {data}=await api.post('/nativephp/actions',form);message.value=data.message;await load()}catch(e){error.value=e.response?.data?.error??'No fue posible preparar la acción.'}finally{busy.value=false}}
async function sync(){busy.value=true;error.value='';try{const {data}=await api.post('/nativephp/sync',{connectivity:'online'});message.value=data.message;await load()}catch(e){error.value=e.response?.data?.error??'No fue posible sincronizar.'}finally{busy.value=false}}
onMounted(load);
</script>
<style scoped>.native-page{max-width:1000px;margin:auto}.native-page__eyebrow{color:#2563eb;font-weight:700;font-size:.85rem}.native-page h1{margin:.25rem 0}.native-page__grid{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-top:1.25rem}.native-page__card{padding:1.25rem;background:#fff;border:1px solid #cbd5e1;border-radius:.5rem}.native-page form{display:grid;gap:.75rem}.native-page label{display:grid;gap:.3rem;font-weight:600}.native-page input,.native-page textarea{padding:.6rem;border:1px solid #94a3b8;border-radius:.3rem;font:inherit}.native-page button{padding:.65rem 1rem;border:0;border-radius:.3rem;background:#2563eb;color:#fff;font-weight:700;cursor:pointer}.native-page button:disabled{opacity:.6}.native-page li{display:flex;gap:.75rem;align-items:center;margin:.8rem 0}.native-page li span{color:#166534}.native-page small{display:block;color:#64748b}.native-page__message{padding:.7rem;background:#dcfce7;color:#166534}.native-page__error{padding:.7rem;background:#fee2e2;color:#991b1b}@media(max-width:700px){.native-page__grid{grid-template-columns:1fr}}
</style>
